from pwn import *

class Node:
    def __init__(self, addr, min_val, max_val, left=None, right=None):
        self.addr = addr
        self.min_val = min_val
        self.max_val = max_val
        self.left = left
        self.right = right

def parse_addr(line):
    try:
        return line.split(':')[1].strip().split()[0]
    except:
        return None

def parse_byte(line):
    try:
        return int(line.split(':')[1].strip().split()[0], 16)
    except:
        return None

def map_bst(gdb, root_addr, visited=None):
    if visited is None:
        visited = set()

    if root_addr == '0x0' or root_addr in visited:
        return None

    visited.add(root_addr)

    # Get node value range
    gdb.sendline(f'x/2xb {root_addr}+0x8'.encode())
    value_range = gdb.recvuntil(b'(gdb) ').decode()
    value_lines = value_range.strip().split('\n')
    if len(value_lines) < 1:
        return None

    # Extract min and max values
    try:
        vals = value_lines[0].split(':')[1].strip().split()
        min_val = int(vals[0], 16)
        max_val = int(vals[1], 16)
    except:
        return None

    # Get left child
    gdb.sendline(f'x/gx {root_addr}+0x10'.encode())
    left_addr = parse_addr(gdb.recvuntil(b'(gdb) ').decode())

    # Get right child
    gdb.sendline(f'x/gx {root_addr}+0x18'.encode())
    right_addr = parse_addr(gdb.recvuntil(b'(gdb) ').decode())

    # Create node
    node = Node(root_addr, min_val, max_val)

    # Recursively map children
    if left_addr and left_addr != '0x0':
        node.left = map_bst(gdb, left_addr, visited)
    if right_addr and right_addr != '0x0':
        node.right = map_bst(gdb, right_addr, visited)

    return node

def print_bst(node, level=0):
    if not node:
        return

    indent = "  " * level
    print(f"{indent}Node at {node.addr}")
    print(f"{indent}Value range: {node.min_val}-{node.max_val}")

    if node.left:
        print(f"{indent}Left child:")
        print_bst(node.left, level + 1)
    if node.right:
        print(f"{indent}Right child:")
        print_bst(node.right, level + 1)

def find_valid_path(node, target):
    if not node:
        return False

    if node.min_val <= target <= node.max_val:
        return True

    if target < node.min_val:
        return find_valid_path(node.left, target)
    else:
        return find_valid_path(node.right, target)

def main():
    # Start GDB
    script = '''
    set pagination off
    b *main
    run
    '''
    with open('gdb_commands.txt', 'w') as f:
        f.write(script)

    p = process(['gdb', '-x', 'gdb_commands.txt', './ctf_files/rabbithole'])
    p.recvuntil(b'(gdb) ')

    try:
        # Get roots array
        p.sendline(b'x/64gx &roots')
        roots_data = p.recvuntil(b'(gdb) ').decode()

        # Extract root addresses
        root_addrs = []
        for line in roots_data.split('\n'):
            if line and ': ' in line:
                values = line.split(':')[1].strip().split()
                root_addrs.extend(values)

        # Map first few BSTs
        print("\nMapping first 5 BSTs:")
        bsts = []
        for i, addr in enumerate(root_addrs[:5]):
            if addr == '0x0':
                continue
            print(f"\nBST at position {i}:")
            bst = map_bst(p, addr)
            if bst:
                print_bst(bst)
                bsts.append(bst)

        # Find valid paths for some ASCII ranges
        print("\nTesting some ASCII paths:")
        for i, bst in enumerate(bsts):
            print(f"\nBST {i} valid characters:")
            valid_chars = []
            for c in range(32, 127):  # printable ASCII
                if find_valid_path(bst, c):
                    valid_chars.append(chr(c))
            print(f"Valid characters: {''.join(valid_chars)}")

    except Exception as e:
        print(f"Error: {e}")
    finally:
        p.close()

if __name__ == '__main__':
    main()

