from pwn import *

def setup_gdb():
    # Create GDB script
    gdb_commands = '''
    set pagination off
    set logging overwrite on
    set logging file gdb.txt
    set logging on
    file ctf_files/rabbithole
    start
    '''
    with open('gdb_commands.txt', 'w') as f:
        f.write(gdb_commands)

    # Start GDB
    p = process(['gdb', '-x', 'gdb_commands.txt', '-q'])
    return p

def analyze_bst_node(gdb, addr):
    # Get node structure (24 bytes total)
    gdb.sendline(f'x/24xb {addr}')
    gdb.sendline(f'p *(char**)({addr}+0x10)') # left child
    gdb.sendline(f'p *(char**)({addr}+0x18)') # right child
    gdb.sendline(f'p *(char*)({addr}+0x8)') # value/range start
    gdb.sendline(f'p *(char*)({addr}+0x9)') # range end

    output = gdb.recvuntil('(gdb)', timeout=1).decode('latin-1')

    node_info = {
        'addr': addr,
        'left': None,
        'right': None,
        'value': None,
        'range_start': None,
        'range_end': None
    }

    # Parse output
    lines = output.split('\n')
    for line in lines:
        if '=' in line:
            try:
                val = line.split('=')[1].strip()
                if 'char *' in val:
                    addr = val.split()[-1]
                    if addr != '0x0':
                        if node_info['left'] is None:
                            node_info['left'] = addr
                        else:
                            node_info['right'] = addr
                elif val.isdigit() or (val.startswith('-') and val[1:].isdigit()):
                    val = int(val)
                    if node_info['value'] is None:
                        node_info['value'] = val
                    elif node_info['range_start'] is None:
                        node_info['range_start'] = val
                    else:
                        node_info['range_end'] = val
            except:
                continue

    return node_info

def traverse_bst(gdb, root_addr, pos=0, path=""):
    if not root_addr or root_addr == "0x0":
        return []

    node = analyze_bst_node(gdb, root_addr)
    results = []

    if node:
        print(f"\nNode at {node['addr']} (Position {pos}):")
        print(f"Value: {node['value']}")
        print(f"Range: {node['range_start']}-{node['range_end']}")
        print(f"Left: {node['left']}")
        print(f"Right: {node['right']}")
        print(f"Path: {path}")

        # If this is a leaf node with a valid range
        if node['range_start'] is not None and node['range_end'] is not None:
            for c in range(node['range_start'], node['range_end'] + 1):
                results.append({
                    'position': pos,
                    'char': chr(c),
                    'ascii': c,
                    'path': path
                })

        # Traverse children
        if node['left']:
            results.extend(traverse_bst(gdb, node['left'], pos, path + "L"))
        if node['right']:
            results.extend(traverse_bst(gdb, node['right'], pos, path + "R"))

    return results

def main():
    print("Starting BST analysis...")
    gdb = setup_gdb()

    # Get roots array
    gdb.sendline('x/12gx &roots')
    roots_output = gdb.recvuntil('(gdb)', timeout=1).decode('latin-1')
    print("\nRoots array:")
    print(roots_output)

    # Extract root addresses
    root_addrs = []
    for line in roots_output.split('\n'):
        if ': ' in line:
            values = line.split(':')[1].strip().split()
            root_addrs.extend(addr for addr in values if addr != '0x0')

    # Analyze first two BSTs
    all_results = []
    for i, root in enumerate(root_addrs[:2]):
        print(f"\nAnalyzing BST {i}:")
        results = traverse_bst(gdb, root, i)
        if results:
            print(f"\nValid characters for BST {i}:")
            for r in results:
                print(f"Position {r['position']}: '{r['char']}' (ASCII: {r['ascii']}) - Path: {r['path']}")
            all_results.extend(results)

    # Organize results by position
    print("\nSummary of findings:")
    pos_results = {}
    for r in all_results:
        pos = r['position']
        if pos not in pos_results:
            pos_results[pos] = []
        pos_results[pos].append(r)

    for pos in sorted(pos_results.keys()):
        print(f"\nPosition {pos} valid characters:")
        chars = pos_results[pos]
        for c in chars:
            print(f"'{c['char']}' via path {c['path']}")

    gdb.close()

if __name__ == '__main__':
    main()

