from pwn import *
import re

class GDBWrapper:
    def __init__(self, proc):
        self.proc = proc

    def execute(self, cmd):
        self.proc.sendline(cmd.encode())
        self.proc.recvuntil(b'(gdb) ')
        return self.proc.clean().decode()

    def get_value(self, cmd):
        output = self.execute(cmd)
        # Extract hex value after ':'
        match = re.search(r':\s*(0x[0-9a-fA-F]+)', output)
        if match:
            return int(match.group(1), 16)
        return 0

def get_node_info(gdb, addr):
    if addr == 0:
        return None

    # Get node values at the given address
    min_val = gdb.get_value(f'x/b {addr}+8')
    max_val = gdb.get_value(f'x/b {addr}+9')
    left = gdb.get_value(f'x/gx {addr}+0x10')
    right = gdb.get_value(f'x/gx {addr}+0x18')

    return {
        'min': min_val,
        'max': max_val,
        'left': left,
        'right': right
    }

def find_valid_chars(gdb, root_addr, visited=None):
    if visited is None:
        visited = set()

    if root_addr == 0 or root_addr in visited:
        return set()

    visited.add(root_addr)
    node = get_node_info(gdb, root_addr)
    if not node:
        return set()

    valid_chars = set()

    # If this is a leaf node (child pointers are 0), this is a valid character
    if node['left'] == 0 and node['right'] == 0:
        for i in range(node['min'], node['max'] + 1):
            valid_chars.add(i)

    # Traverse left and right children
    if node['left']:
        valid_chars.update(find_valid_chars(gdb, node['left'], visited))
    if node['right']:
        valid_chars.update(find_valid_chars(gdb, node['right'], visited))

    return valid_chars

def main():
    binary = '/home/ctfplayer/ctf_files/rabbithole'

    # Start GDB
    p = process(['gdb', '-q', binary])
    p.recvuntil(b'(gdb) ')
    gdb = GDBWrapper(p)

    # Set breakpoint at main and run
    gdb.execute('break main')
    gdb.execute('run')

    # Get roots array address
    output = gdb.execute('p &roots')
    roots_addr = int(re.search(r'= (0x[0-9a-fA-F]+)', output).group(1), 16)

    # There are 59 (0x3b) positions in the flag
    flag_chars = []
    for i in range(59):
        # Get root address for this position
        root_ptr = gdb.get_value(f'x/gx {roots_addr + (i*8)}')

        # Find valid characters for this position
        valid = find_valid_chars(gdb, root_ptr)
        if valid:
            char = chr(min(valid))  # Take first valid character
            flag_chars.append(char)
        else:
            flag_chars.append('?')

    flag = ''.join(flag_chars)
    print(f"Extracted flag: {flag}")

    # Clean up
    gdb.execute('quit')
    p.close()

if __name__ == '__main__':
    main()

