from pwn import *
import re

class GDBWrapper:
    def __init__(self, binary):
        self.proc = process(['gdb', '-q', binary])
        self.recv_until_prompt()

    def recv_until_prompt(self):
        self.proc.recvuntil(b'(gdb) ')

    def execute(self, command):
        self.proc.sendline(command.encode())
        output = self.proc.recvuntil(b'(gdb) ').decode()
        return output.split('\n')[0]  # Return first line only

    def quit(self):
        self.proc.sendline(b'quit')
        self.proc.close()

def find_roots_addr(gdb):
    # Set breakpoint and run
    gdb.execute('set pagination off')
    gdb.execute('break *main+100')  # Break after roots initialization
    gdb.execute('run')

    # Try to find roots symbol
    gdb.execute('print &roots')
    roots_output = gdb.execute('p &roots')
    match = re.search(r'= \(char \*\*\) (0x[0-9a-fA-F]+)', roots_output)

    if match:
        return int(match.group(1), 16)
    return None

def get_node_info(gdb, node_addr):
    if node_addr == 0:
        return None

    try:
        # Get min and max values
        min_val = int(gdb.execute(f'x/1bu {node_addr}+8').split(':')[1].strip(), 16)
        max_val = int(gdb.execute(f'x/1bu {node_addr}+9').split(':')[1].strip(), 16)

        # Get child pointers
        left = int(gdb.execute(f'x/gx {node_addr}+0x10').split(':')[1].strip(), 16)
        right = int(gdb.execute(f'x/gx {node_addr}+0x18').split(':')[1].strip(), 16)

        return {
            'min': min_val,
            'max': max_val,
            'left': left,
            'right': right
        }
    except:
        return None

def get_valid_chars(gdb, node_addr, depth=0, max_depth=100):
    if depth > max_depth or node_addr == 0:
        return set()

    node = get_node_info(gdb, node_addr)
    if not node:
        return set()

    valid = set()

    # If leaf node, add range of valid chars
    if node['left'] == 0 and node['right'] == 0:
        for i in range(node['min'], node['max'] + 1):
            if 32 <= i <= 126:  # Printable ASCII only
                valid.add(i)

    # Traverse children
    valid.update(get_valid_chars(gdb, node['left'], depth + 1))
    valid.update(get_valid_chars(gdb, node['right'], depth + 1))

    return valid

def main():
    try:
        binary = '/home/ctfplayer/ctf_files/rabbithole'
        gdb = GDBWrapper(binary)

        # Find roots array
        roots_addr = find_roots_addr(gdb)
        if not roots_addr:
            print("Could not find roots array")
            return

        print(f"Found roots array at {hex(roots_addr)}")

        # Process each position in the flag
        flag = []
        flag_len = 59  # Known flag length

        for i in range(flag_len):
            # Get root node pointer for this position
            root_ptr_output = gdb.execute(f'x/gx {roots_addr}+{i*8}')
            root_addr = int(root_ptr_output.split(':')[1].strip(), 16)

            if root_addr == 0:
                flag.append('?')
                continue

            # Find valid characters for this position
            valid_chars = get_valid_chars(gdb, root_addr)

            if valid_chars:
                char = chr(min(valid_chars))
                flag.append(char)
                print(f"Position {i}: Valid char '{char}' (0x{ord(char):02x})")
            else:
                flag.append('?')
                print(f"Position {i}: No valid chars found")

        flag_str = ''.join(flag)
        print(f"\nExtracted flag: {flag_str}")

    except Exception as e:
        print(f"Error: {str(e)}")
    finally:
        if 'gdb' in locals():
            gdb.quit()

if __name__ == '__main__':
    main()

